def extract_story(name, raw):
    if name not in BOUNDARIES:
        raise ValueError(f"Story boundaries for {name} have not been verified.")
    start_pattern, end_pattern = BOUNDARIES[name]
    start = re.search(start_pattern, raw, re.IGNORECASE)
    endings = list(re.finditer(end_pattern, raw, re.IGNORECASE))
    if start is None or not endings or endings[-1].end() <= start.start():
        raise ValueError(f"Reliable story boundaries not found for {name}.")
    return unwrap_story(raw[start.start():endings[-1].end()])

def decode(tokens: list[int]) -> str:
    # An unfinished or invalid UTF-8 sequence is visible as a replacement character.
    return bytes(tokens).decode("utf-8", errors="replace")

def batch(data, context, batch_size, rng, device):
    starts = torch.randint(len(data) - context, (batch_size,), generator=rng)
    offsets = torch.arange(context)
    x = data[starts[:, None] + offsets]
    y = data[starts[:, None] + offsets + 1]
    return x.to(device), y.to(device)

def forward(self, tokens, targets=None):
    if tokens.ndim != 2 or not 1 <= tokens.shape[1] <= self.config.context:
        raise ValueError("Input must have shape [batch, 1..context].")
    positions = torch.arange(tokens.shape[1], device=tokens.device)
    x = self.embedding_dropout(self.token(tokens) + self.position(positions))
    x = self.final_norm(self.blocks(x))

def forward(self, x):
    batch, length, width = x.shape
    q, k, v = self.qkv(x).chunk(3, dim=-1)
    q, k, v = [
        t.view(batch, length, self.heads, width // self.heads).transpose(1, 2)
        for t in (q, k, v)
    ]

def forward(self, x):
    x = x + self.attention(self.ln1(x))
    return x + self.mlp(self.ln2(x))

def _initialize(module):
    if isinstance(module, (nn.Linear, nn.Embedding)):
        nn.init.normal_(module.weight, std=0.02)
        if isinstance(module, nn.Linear):
            nn.init.zeros_(module.bias)

def document_batch(documents, context, rng, batch_size=32):
    if not documents or any(len(document) <= context for document in documents):
        raise ValueError("Each training document must contain a complete shifted window.")
    if len(documents) < 2:
        raise ValueError("Expanded training needs the original plus at least one new book.")
    weights = torch.tensor([0.5] + [0.5 / (len(documents) - 1)] * (len(documents) - 1))
    chosen = torch.multinomial(weights, batch_size, replacement=True, generator=rng)
    x = torch.empty((batch_size, context), dtype=torch.long)
    y = torch.empty_like(x)

def suite(model, documents, positions, device):
    per_book = {name: evaluate(model, content, positions[name], device)
                for name, content in documents.items()}
    new_metrics = [per_book[book["name"]] for book in BOOKS]
    macro = combine(new_metrics, [1 / len(new_metrics)] * len(new_metrics))
    combined = combine([per_book["original"], macro], [0.5, 0.5])
    return dict(per_book=per_book, new_books_macro=macro, combined=combined)

